from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + skill[i]

        start = 0
        for j in range(len(mana) - 1):
            best = 0
            for i in range(n):
                delay = prefix[i + 1] * mana[j] - prefix[i] * mana[j + 1]
                if delay > best:
                    best = delay
            start += best

        return start + prefix[n] * mana[-1]
